// uncompressed public key is listed once (the two files' keys in one list) and
// each case names its key by index and carries its hash, and the per-case
// comments and flags are left out. Every case of both files is kept, and every
// value kept is as upstream wrote it. `tests/link/crypto_p384` and
// `crypto_p384_f64` run them.

/** One P-384 ECDSA case: its id, its key, the hash (256 or 384), the expected result, and the message and signature in hex (DER or `r || s`, as each list says). */
export interface P384VectorCase {
  // `number` rather than `i32`, so the file compiles in either number mode: a
  // bare literal in an object literal takes the mode's width.
  tcId: number;
  key: number;
  hash: number;
  result: string;
  msg: string;
  sig: string;
}

